-- Upcoming or scheduled appointment(s) attached to a waiting list card.

CREATE TABLE cardiology_waiting_list_card_appointment (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    deleted_at TIMESTAMPTZ DEFAULT NULL,
    cardiology_waiting_list_card_id UUID NOT NULL
        REFERENCES cardiology_waiting_list_card(id) ON DELETE CASCADE,

    appointment_date DATE,
    appointment_time TIME,
    duration_minutes INTEGER
        CHECK (duration_minutes IS NULL OR duration_minutes BETWEEN 1 AND 1440),
    appointment_type VARCHAR(30) NOT NULL DEFAULT ''
        CHECK (appointment_type IN (
            'first-outpatient',
            'follow-up',
            'pre-assessment',
            'diagnostic',
            'treatment',
            'procedure',
            'admission',
            'telephone',
            'video',
            'other',
            ''
        )),
    site_name VARCHAR(255) NOT NULL DEFAULT '',
    site_address TEXT NOT NULL DEFAULT '',
    clinic_name VARCHAR(255) NOT NULL DEFAULT '',
    room VARCHAR(100) NOT NULL DEFAULT '',
    clinician_name VARCHAR(255) NOT NULL DEFAULT '',
    clinician_team VARCHAR(255) NOT NULL DEFAULT '',
    status VARCHAR(20) NOT NULL DEFAULT 'scheduled'
        CHECK (status IN ('scheduled', 'confirmed', 'rebooked', 'cancelled', 'attended', 'did-not-attend')),
    travel_notes TEXT NOT NULL DEFAULT '',
    access_notes TEXT NOT NULL DEFAULT ''
);

CREATE TRIGGER trigger_cardiology_waiting_list_card_appointment_updated_at
    BEFORE UPDATE ON cardiology_waiting_list_card_appointment
    FOR EACH ROW
    EXECUTE FUNCTION set_updated_at();

CREATE INDEX index_cardiology_waiting_list_card_appointment_card_id
    ON cardiology_waiting_list_card_appointment(cardiology_waiting_list_card_id);

CREATE INDEX index_cardiology_waiting_list_card_appointment_date
    ON cardiology_waiting_list_card_appointment(appointment_date);

COMMENT ON TABLE cardiology_waiting_list_card_appointment IS
