-- Audit trail of rules that fired during grading of a waiting list card.

CREATE TABLE cardiology_waiting_list_card_grade_rule (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    deleted_at TIMESTAMPTZ DEFAULT NULL,
    cardiology_waiting_list_card_grade_id UUID NOT NULL
        REFERENCES cardiology_waiting_list_card_grade(id) ON DELETE CASCADE,
    rule_id VARCHAR(50) NOT NULL,
    instrument VARCHAR(30) NOT NULL
        CHECK (instrument IN ('waiting-time-status', 'clinical-priority', 'long-wait')),
    band VARCHAR(20) NOT NULL DEFAULT ''
        CHECK (band IN (
            'within-target',
            'approaching-breach',
            'breached',
            'long-wait',
            ''
        )),
    category VARCHAR(50) NOT NULL DEFAULT '',
    description VARCHAR(500) NOT NULL DEFAULT ''
);

CREATE TRIGGER trigger_cardiology_waiting_list_card_grade_rule_updated_at
    BEFORE UPDATE ON cardiology_waiting_list_card_grade_rule
    FOR EACH ROW
    EXECUTE FUNCTION set_updated_at();

CREATE INDEX index_cardiology_waiting_list_card_grade_rule_grade_id
    ON cardiology_waiting_list_card_grade_rule(cardiology_waiting_list_card_grade_id);

COMMENT ON TABLE cardiology_waiting_list_card_grade_rule IS
    'Audit trail of every waiting-time-status / clinical-priority / long-wait rule that fired during grading of a waiting list card.';
COMMENT ON COLUMN cardiology_waiting_list_card_grade_rule.id IS
    'Primary key UUID, auto-generated.';
COMMENT ON COLUMN cardiology_waiting_list_card_grade_rule.created_at IS
    'Timestamp when the record was created.';
COMMENT ON COLUMN cardiology_waiting_list_card_grade_rule.updated_at IS
    'Timestamp when the record was updated most-recently.';
COMMENT ON COLUMN cardiology_waiting_list_card_grade_rule.deleted_at IS
    'Timestamp when the record was deleted a.k.a. soft-removed.';
COMMENT ON COLUMN cardiology_waiting_list_card_grade_rule.cardiology_waiting_list_card_grade_id IS
    'Foreign key to the parent grade row.';
COMMENT ON COLUMN cardiology_waiting_list_card_grade_rule.rule_id IS
    'Stable rule identifier (e.g. R-WTS-BREACHED-001).';
COMMENT ON COLUMN cardiology_waiting_list_card_grade_rule.instrument IS
    'Scoring instrument the rule belongs to: waiting-time-status, clinical-priority, long-wait.';
COMMENT ON COLUMN cardiology_waiting_list_card_grade_rule.band IS
    'Band contributed by this rule (e.g. breached).';
COMMENT ON COLUMN cardiology_waiting_list_card_grade_rule.category IS
    'Category descriptor (e.g. rtt-18-week, priority-target, long-waiter).';
COMMENT ON COLUMN cardiology_waiting_list_card_grade_rule.description IS
    'Human-readable description of why the rule fired.';

-- ========================================================================
-- END 07_create_table_cardiology_waiting_list_card_grade_rule.sql
-- ========================================================================

-- ========================================================================
-- BEGIN 08_create_table_cardiology_waiting_list_card_grade_flag.sql
-- ========================================================================

-- Safety / operational flags that fire independently of the Waiting Time Status.

CREATE TABLE cardiology_waiting_list_card_grade_flag (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    deleted_at TIMESTAMPTZ DEFAULT NULL,
    cardiology_waiting_list_card_grade_id UUID NOT NULL
        REFERENCES cardiology_waiting_list_card_grade(id) ON DELETE CASCADE,
    flag_id VARCHAR(50) NOT NULL,
    category VARCHAR(50) NOT NULL DEFAULT ''
        CHECK (category IN (
            'breach-risk',
            'long-waiter-52-week',
            'priority-1-escalation',
            'two-week-wait-cancer',
            'missing-appointment',
            'accessibility-unmet',
            'interpreter-required',
            'contact-details-missing',
            'other',
            ''
        )),
    priority VARCHAR(10) NOT NULL DEFAULT ''
        CHECK (priority IN ('low', 'medium', 'high', '')),
    description VARCHAR(500) NOT NULL DEFAULT '',
    suggested_action VARCHAR(500) NOT NULL DEFAULT ''
);

CREATE TRIGGER trigger_cardiology_waiting_list_card_grade_flag_updated_at
    BEFORE UPDATE ON cardiology_waiting_list_card_grade_flag
    FOR EACH ROW
    EXECUTE FUNCTION set_updated_at();

CREATE INDEX index_cardiology_waiting_list_card_grade_flag_grade_id
    ON cardiology_waiting_list_card_grade_flag(cardiology_waiting_list_card_grade_id);

COMMENT ON TABLE cardiology_waiting_list_card_grade_flag IS
    'Safety / operational flags that fire independently of the Waiting Time Status, with priority and a suggested action for the booking team.';
COMMENT ON COLUMN cardiology_waiting_list_card_grade_flag.id IS
    'Primary key UUID, auto-generated.';
COMMENT ON COLUMN cardiology_waiting_list_card_grade_flag.created_at IS
    'Timestamp when the record was created.';
COMMENT ON COLUMN cardiology_waiting_list_card_grade_flag.updated_at IS
    'Timestamp when the record was updated most-recently.';
COMMENT ON COLUMN cardiology_waiting_list_card_grade_flag.deleted_at IS
    'Timestamp when the record was deleted a.k.a. soft-removed.';
COMMENT ON COLUMN cardiology_waiting_list_card_grade_flag.cardiology_waiting_list_card_grade_id IS
    'Foreign key to the parent grade row.';
COMMENT ON COLUMN cardiology_waiting_list_card_grade_flag.flag_id IS
    'Stable flag identifier (e.g. F-BREACH-RISK-001).';
COMMENT ON COLUMN cardiology_waiting_list_card_grade_flag.category IS
    'Flag category.';
COMMENT ON COLUMN cardiology_waiting_list_card_grade_flag.priority IS
    'Priority: low, medium, high.';
COMMENT ON COLUMN cardiology_waiting_list_card_grade_flag.description IS
    'Human-readable description of what fired the flag.';
COMMENT ON COLUMN cardiology_waiting_list_card_grade_flag.suggested_action IS
    'Suggested action (e.g. "contact patient to confirm next appointment").';

-- ========================================================================
-- END 08_create_table_cardiology_waiting_list_card_grade_flag.sql
-- ========================================================================
